<script>
	// the array family measures a blank line from PAST the comma, so a blank the author
	// left before a comma of its own is layout rather than authorship — and a comment
	// between the blank and the comma does not hide the comma from the scan
	const a = [
		a1,
		// c1
		b1
	];

	// authored the other way round, the blank sits after the comma and survives
	const b = [
		a2,

		// c2
		b2
	];
</script>
